<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue';import P6Dialog from './P6Dialog.vue';
type Row={id:string;[k:string]:any};type Request=<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;
const props=defineProps<{request:Request;readonly:boolean;access:any;memberId:string;mode:'tickets'|'complaints'|'statistics'}>();
const rows=ref<Row[]>([]),owners=ref<Row[]>([]),customers=ref<Row[]>([]),types=ref<Row[]>([]),statistics=ref<Row[]>([]),page=ref(1),total=ref(0),q=ref(''),state=ref(''),type=ref(''),busy=ref(false),error=ref(''),success=ref(''),dialog=ref(''),selected=ref<Row|null>(null),link=ref(''),key=ref('');
const customerQuery=ref(''),customerPage=ref(1),customerTotal=ref(0);
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());const from=ref(today.slice(0,7)+'-01'),to=ref(today);
const form=reactive({title:'',description:'',customerId:'',assigneeMemberId:'',priority:'NORMAL',typeCode:'SERVICE',reason:'',body:'',kind:'PUBLIC_REPLY'});const targets=reactive([{priority:'URGENT',responseMinutes:60,resolutionMinutes:480},{priority:'HIGH',responseMinutes:240,resolutionMinutes:1440},{priority:'NORMAL',responseMinutes:480,resolutionMinutes:4320},{priority:'LOW',responseMinutes:1440,resolutionMinutes:10080}]);const policy=reactive({id:'',name:'企业服务标准',pauseWaiting:true,escalate:true,active:true,version:0});
const labels:Record<string,string>={NEW:'待接单',IN_PROGRESS:'处理中',WAITING_CUSTOMER:'等待客户',RESOLVED:'已解决',CLOSED:'已关闭',CANCELLED:'已取消',URGENT:'紧急',HIGH:'高',NORMAL:'普通',LOW:'低',PUBLIC_REPLY:'公开回复',INTERNAL_NOTE:'内部记录',ACTIVE:'计时中',PAUSED:'暂停计时',RESPONSE:'响应超时',RESOLUTION:'解决超时'};
const title=computed(()=>props.mode==='complaints'?'客诉工单':props.mode==='statistics'?'服务统计':'服务工单');const canWrite=computed(()=>!props.readonly&&props.access.tickets.write);
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';success.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function load(){if(props.mode==='statistics'){const r=await props.request<any>(`/service/statistics?from=${from.value}&to=${to.value}`);statistics.value=r.items;}else{const r=await props.request<any>(`/tickets?page=${page.value}&pageSize=20&q=${encodeURIComponent(q.value)}&status=${state.value}&typeCode=${props.mode==='complaints'?'COMPLAINT':type.value}`);rows.value=r.items;total.value=r.total;}}
async function options(){const [o,c,d]=await Promise.all([props.request<any>('/tickets/owners'),props.request<any>(`/tickets/customer-options?page=${customerPage.value}&pageSize=20&q=${encodeURIComponent(customerQuery.value)}`),props.request<any>('/configuration').catch(()=>({dictionaries:[]}))]);owners.value=Array.isArray(o)?o:o.items??[];customers.value=c.items;customerTotal.value=c.total;types.value=(d.dictionaries??[]).filter((x:Row)=>x.dictionaryType==='TICKET_TYPE'&&x.active);}
function create(){run(async()=>{customerPage.value=1;customerQuery.value='';await options();Object.assign(form,{title:'',description:'',customerId:'',assigneeMemberId:owners.value[0]?.id??'',priority:'NORMAL',typeCode:props.mode==='complaints'?'COMPLAINT':'SERVICE'});key.value=crypto.randomUUID();dialog.value='create';});}
function save(){run(async()=>{await props.request('/tickets','POST',{title:form.title,description:form.description,customerId:form.customerId||null,assigneeMemberId:form.assigneeMemberId,priority:form.priority,typeCode:form.typeCode,slaPolicyId:policy.id||null,requesterName:'',requesterEmail:'',expectedVersion:0},{'Idempotency-Key':key.value});dialog.value='';await load();success.value='工单已受理并派给负责人';});}
async function detail(id:string){selected.value=await props.request<Row>('/service/tickets/'+id);dialog.value='view';link.value='';}
function view(row:Row){run(()=>detail(row.id));}
function action(act:string){run(async()=>{form.reason='';form.body='';form.kind='PUBLIC_REPLY';form.assigneeMemberId=selected.value?.assigneeMemberId??'';if(act==='dispatch')await options();key.value=crypto.randomUUID();dialog.value=act;});}
function apply(){run(async()=>{const r=selected.value!,act=dialog.value;let path=`/tickets/${r.id}/${act}`,body:any={expectedVersion:r.version,reason:form.reason};if(act==='dispatch'){path=`/service/tickets/${r.id}/dispatch`;body.assigneeMemberId=form.assigneeMemberId;}if(act==='comment'){path=`/tickets/${r.id}/comments`;body={expectedVersion:r.version,body:form.body,kind:form.kind};}await props.request(path,'POST',body,{'Idempotency-Key':key.value});await load();await detail(r.id);success.value='处理已保存';});}
function feedback(){run(async()=>{const r=await props.request<any>(`/service/tickets/${selected.value!.id}/feedback-link`,'POST',{expectedVersion:selected.value!.version,reason:'邀请客户评价本轮服务'});link.value=location.origin+r.path;success.value='评价链接有效7天，每轮服务仅可评价一次；新链接会撤销旧链接';});}
function sla(){run(async()=>{const r=await props.request<any>('/service/sla-policies');const saved=r.items[0];if(saved){Object.assign(policy,{id:saved.id,name:saved.name,pauseWaiting:saved.pauseWaiting,escalate:saved.escalate,active:saved.active,version:saved.version});saved.targets.forEach((x:any,i:number)=>Object.assign(targets[i],x));}key.value=crypto.randomUUID();dialog.value='sla';});}
function saveSla(){run(async()=>{const r=await props.request<any>('/service/sla-policies'+(policy.id?'/'+policy.id:''),policy.id?'PUT':'POST',{name:policy.name,targets:targets.map(t=>({...t,responseMinutes:Number(t.responseMinutes),resolutionMinutes:Number(t.resolutionMinutes)})),pauseWaiting:policy.pauseWaiting,escalate:policy.escalate,active:policy.active,expectedVersion:policy.version},policy.id?{}:{'Idempotency-Key':key.value});policy.id=r.id;dialog.value='';success.value='SLA 已保存，新工单使用该策略；已有工单继续保留原策略';});}
function runSla(){run(async()=>{const r=await props.request<any>('/service/jobs/run','POST');success.value=`已检查超时节点，本次发现 ${r.processed} 项`;});}
function turn(n:number){page.value+=n;run(load);}function time(v:any){return v?new Date(v).toLocaleString('zh-CN'):'—';}function number(v:any){return v==null?'—':v;}
watch(()=>props.mode,()=>{page.value=1;dialog.value='';run(load);});onMounted(()=>run(async()=>{if(canWrite.value){const r=await props.request<any>('/service/sla-policies');policy.id=r.items.find((x:Row)=>x.active)?.id??'';}await load();}));
</script>
<template><section class="p6"><div class="page-heading"><div><span class="eyebrow">CUSTOMER SERVICE</span><h1>{{title}}</h1><p>受理、派工、接单、处理与评价，完整追溯每轮服务。</p></div><div class="p6-actions"><button v-if="access.slaManage&&!readonly" class="btn secondary" @click="sla">SLA 标准</button><button v-if="canWrite&&mode!=='statistics'" class="btn primary" @click="create">受理{{title}}</button></div></div><div v-if="error&&!dialog" class="p6-error" role="alert">{{error}}</div><div v-if="success" class="p6-success" role="status">{{success}}</div><form class="p6-toolbar" @submit.prevent="page=1;run(load)"><template v-if="mode==='statistics'"><label>开始日期<input v-model="from" type="date" :max="today" required/></label><label>结束日期<input v-model="to" type="date" :max="today" required/></label></template><template v-else><label>搜索<input v-model="q" maxlength="100" placeholder="工单编号、主题、客户"/></label><label>状态<select v-model="state"><option value="">全部状态</option><option v-for="s in ['NEW','IN_PROGRESS','WAITING_CUSTOMER','RESOLVED','CLOSED','CANCELLED']" :key="s" :value="s">{{labels[s]}}</option></select></label><label v-if="mode==='tickets'">类型<select v-model="type"><option value="">全部类型</option><option value="SERVICE">服务工单</option><option value="COMPLAINT">客诉工单</option><option value="TECHNICAL">技术支持</option><option value="QUALITY">质量问题</option></select></label></template><button class="btn secondary" :disabled="busy">查询</button><button v-if="access.slaManage&&!readonly" type="button" class="btn secondary" @click="runSla">检查超时</button></form>
<div class="p6-card"><div v-if="mode==='statistics'" class="table-scroll"><table><thead><tr><th>服务人员</th><th>工单 / 完成</th><th>超时</th><th>平均响应 / 服务耗时（分钟）</th><th>满意度 / 评价数</th></tr></thead><tbody><tr v-for="r in statistics" :key="r.memberId"><td>{{r.memberName}}</td><td>{{r.tickets}} / {{r.completed}}</td><td>{{r.breached}}</td><td>{{number(r.responseMinutes)}} / {{number(r.serviceMinutes)}}</td><td>{{number(r.satisfaction)}} / {{r.ratings}}</td></tr><tr v-if="!statistics.length"><td colspan="5">当前日期范围暂无服务记录</td></tr></tbody></table><p class="p6-muted">按工单创建时间筛选、当前服务轮次统计；使用自然时间 SLA，暂停等待客户的时段从服务耗时扣除。</p></div><template v-else><div class="table-scroll"><table><thead><tr><th>编号 / 主题</th><th>客户</th><th>状态 / 优先级</th><th>负责人</th><th>响应截止</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.ticketNumber}}<small>{{r.title}}</small></td><td>{{r.customerName||'独立工单'}}</td><td>{{labels[r.status]}}<small>{{labels[r.priority]}}</small></td><td>{{r.assigneeName}}</td><td>{{time(r.firstResponseDueAt)}}</td><td><button class="text-button" @click="view(r)">查看 / 处理</button></td></tr><tr v-if="!rows.length"><td colspan="6">暂无工单</td></tr></tbody></table></div><div class="p6-pages"><span>共 {{total}} 条 · 第 {{page}} 页</span><button class="btn secondary" :disabled="busy||page===1" @click="turn(-1)">上一页</button><button class="btn secondary" :disabled="busy||page*20>=total" @click="turn(1)">下一页</button></div></template></div>
<P6Dialog v-if="dialog" :title="dialog==='create'?'受理'+title:dialog==='view'?'工单详情':dialog==='sla'?'SLA 服务标准':dialog==='dispatch'?'重新派工':dialog==='comment'?'添加处理记录':'处理工单'" :busy="busy" @close="!busy&&(dialog='')"><div v-if="error" class="p6-error" role="alert">{{error}}</div><template v-if="dialog==='view'&&selected"><h3>{{selected.ticketNumber}} · {{selected.title}}</h3><p class="p6-muted">{{selected.customerName||'独立工单'}} · {{selected.assigneeName}} · {{labels[selected.status]}} · {{labels[selected.priority]}}</p><p class="p6-copy">{{selected.description}}</p><div class="p6-grid"><div><small>派工 / 接单</small><p>{{time(selected.assignedAt)}} / {{time(selected.acceptedAt)}}</p></div><div><small>当前 SLA</small><p>{{labels[selected.slaState]}} · 响应 {{time(selected.firstResponseDueAt)}} · 解决 {{time(selected.resolutionDueAt)}}</p></div></div><div v-if="selected.canWrite&&canWrite" class="p6-actions"><button v-if="selected.status==='NEW'&&selected.assigneeMemberId===memberId" class="btn primary" @click="action('start')">接单并处理</button><button v-if="['NEW','IN_PROGRESS'].includes(selected.status)" class="btn secondary" @click="action('dispatch')">派工 / 转派</button><button v-if="['NEW','IN_PROGRESS','WAITING_CUSTOMER'].includes(selected.status)" class="btn secondary" @click="action('comment')">回复 / 处理记录</button><button v-if="selected.status==='IN_PROGRESS'" class="btn secondary" @click="action('wait')">等待客户</button><button v-if="selected.status==='WAITING_CUSTOMER'" class="btn secondary" @click="action('resume')">恢复处理</button><button v-if="selected.status==='IN_PROGRESS'" class="btn primary" @click="action('resolve')">完成解决</button><button v-if="selected.status==='RESOLVED'" class="btn secondary" @click="action('close')">关闭工单</button><template v-if="['RESOLVED','CLOSED'].includes(selected.status)"><button class="btn secondary" @click="feedback">生成客户评价链接</button><button class="btn secondary" @click="action('reopen')">重新打开</button></template><button v-if="selected.status==='NEW'" class="btn secondary" @click="action('cancel')">取消工单</button></div><div v-if="link" class="p6-link"><p>复制此链接交给客户，有效期7天：</p><a :href="link" target="_blank" rel="noopener noreferrer">{{link}}</a></div><h3>处理记录</h3><div v-for="c in selected.comments?.items||[]" :key="c.id" class="p6-record"><small class="p6-muted">{{labels[c.kind]}} · {{c.actorNameSnapshot}} · {{time(c.createdAt)}}</small><p class="p6-copy">{{c.body}}</p></div><h3>SLA 与升级</h3><div v-for="e in selected.sla?.episodes||[]" :key="e.id" class="p6-record">第 {{e.cycleNo}} 轮 · {{labels[e.state]}} · 解决 {{time(e.resolvedAt)}}</div><div v-for="b in selected.sla?.breaches||[]" :key="b.id" class="p6-record">{{labels[b.kind]}} · {{time(b.detectedAt)}} · 已按策略通知负责人</div><h3>客户评价</h3><div v-for="(f,i) in selected.feedback||[]" :key="i" class="p6-record">第 {{f.cycleNo}} 轮 · {{f.submittedAt?f.score+' / 5 分':f.revokedAt?'已撤销':'等待评价'}}<p class="p6-copy">{{f.comment}}</p></div></template>
<form v-else @submit.prevent="dialog==='create'?save():dialog==='sla'?saveSla():apply()"><fieldset :disabled="busy||readonly"><template v-if="dialog==='create'"><label>主题<input v-model="form.title" required maxlength="200"/></label><div class="p6-actions"><input v-model="customerQuery" placeholder="搜索客户名称" maxlength="100"/><button class="btn secondary" type="button" @click="run(async()=>{customerPage=1;await options()})">搜索客户</button></div><label>客户<select v-model="form.customerId"><option value="">独立工单</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}}</option></select></label><div class="p6-pages"><span>共 {{customerTotal}} 家</span><button class="btn secondary" type="button" :disabled="customerPage===1" @click="run(async()=>{customerPage--;await options()})">上一页</button><button class="btn secondary" type="button" :disabled="customerPage*20>=customerTotal" @click="run(async()=>{customerPage++;await options()})">下一页</button></div><div class="p6-grid"><label>派工人员<select v-model="form.assigneeMemberId" required><option v-for="o in owners" :key="o.id" :value="o.id">{{o.name}}</option></select></label><label>优先级<select v-model="form.priority"><option v-for="s in ['URGENT','HIGH','NORMAL','LOW']" :key="s" :value="s">{{labels[s]}}</option></select></label><label>类型<select v-model="form.typeCode"><option value="COMPLAINT">客诉工单</option><option value="SERVICE">服务工单</option><option v-for="r in types.filter(x=>!['COMPLAINT','SERVICE'].includes(x.itemCode))" :key="r.id" :value="r.itemCode">{{r.label}}</option></select></label></div><label>问题说明<textarea v-model="form.description" rows="5" maxlength="10000"/></label></template><template v-else-if="dialog==='sla'"><label>标准名称<input v-model="policy.name" maxlength="100" required/></label><div v-for="t in targets" :key="t.priority" class="p6-grid"><label>{{labels[t.priority]}} · 首次响应分钟<input v-model.number="t.responseMinutes" type="number" min="1" max="43200" required/></label><label>解决分钟<input v-model.number="t.resolutionMinutes" type="number" :min="t.responseMinutes" max="43200" required/></label></div><label><span><input v-model="policy.pauseWaiting" type="checkbox" style="width:auto"/> 等待客户时暂停计时</span></label><label><span><input v-model="policy.escalate" type="checkbox" style="width:auto"/> 超时升级通知主管</span></label><p class="p6-muted">自然时间24×7。此处保存后，新工单采用该标准；已受理工单保留原 SLA 快照。</p></template><template v-else-if="dialog==='comment'"><label>记录类型<select v-model="form.kind"><option value="PUBLIC_REPLY">公开回复（客户可见）</option><option value="INTERNAL_NOTE">内部处理记录</option></select></label><label>内容<textarea v-model="form.body" rows="5" maxlength="4000" required/></label></template><template v-else><label v-if="dialog==='dispatch'">接单人员<select v-model="form.assigneeMemberId" required><option v-for="o in owners" :key="o.id" :value="o.id">{{o.name}}</option></select></label><p v-if="dialog==='dispatch'" class="p6-muted">转派后由新负责人接单，SLA 截止时间继续沿用。</p><label>处理说明<textarea v-model="form.reason" rows="4" maxlength="500" required/></label></template></fieldset><button class="btn primary" :disabled="busy||readonly">{{busy?'处理中…':'确认保存'}}</button></form></P6Dialog></section></template>
